DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[ProductVendor]([ProductID],[BusinessEntityID],[AverageLeadTime],[StandardPrice],[LastReceiptCost],[LastReceiptDate],[MinOrderQty],[MaxOrderQty],[OnOrderQty],[UnitMeasureCode],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[BusinessEntityID],S.[AverageLeadTime],S.[StandardPrice],S.[LastReceiptCost],S.[LastReceiptDate],S.[MinOrderQty],S.[MaxOrderQty],S.[OnOrderQty],S.[UnitMeasureCode],S.[ModifiedDate],@B FROM ssis_flow.Delta_ProductVendor S;
INSERT stg.[ProductVendor]([ProductID],[BusinessEntityID],[AverageLeadTime],[StandardPrice],[LastReceiptCost],[LastReceiptDate],[MinOrderQty],[MaxOrderQty],[OnOrderQty],[UnitMeasureCode],[ModifiedDate],LoadBatchID) SELECT [ProductID],[BusinessEntityID],[AverageLeadTime],[StandardPrice],[LastReceiptCost],[LastReceiptDate],[MinOrderQty],[MaxOrderQty],[OnOrderQty],[UnitMeasureCode],[ModifiedDate],@B FROM etl_raw.[ProductVendor];
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.ProductVendor','I',@Next,(SELECT R.[ProductID],R.[BusinessEntityID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[ProductVendor] R;
END ELSE BEGIN
SELECT [ProductID],[BusinessEntityID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_ProductVendor FROM ssis_flow.Delta_ProductVendor;
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.ProductVendor',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[ProductID],C.[BusinessEntityID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_ProductVendor C LEFT JOIN etl_raw.[ProductVendor] R ON R.[ProductID]=C.[ProductID] AND R.[BusinessEntityID]=C.[BusinessEntityID];
DELETE R FROM etl_raw.[ProductVendor] R JOIN #CT_ProductVendor C ON R.[ProductID]=C.[ProductID] AND R.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[AverageLeadTime]=S.[AverageLeadTime],R.[StandardPrice]=S.[StandardPrice],R.[LastReceiptCost]=S.[LastReceiptCost],R.[LastReceiptDate]=S.[LastReceiptDate],R.[MinOrderQty]=S.[MinOrderQty],R.[MaxOrderQty]=S.[MaxOrderQty],R.[OnOrderQty]=S.[OnOrderQty],R.[UnitMeasureCode]=S.[UnitMeasureCode],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[ProductVendor] R JOIN #CT_ProductVendor C ON R.[ProductID]=C.[ProductID] AND R.[BusinessEntityID]=C.[BusinessEntityID] JOIN ssis_flow.Delta_ProductVendor S ON S.[ProductID]=C.[ProductID] AND S.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[ProductVendor]([ProductID],[BusinessEntityID],[AverageLeadTime],[StandardPrice],[LastReceiptCost],[LastReceiptDate],[MinOrderQty],[MaxOrderQty],[OnOrderQty],[UnitMeasureCode],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[BusinessEntityID],S.[AverageLeadTime],S.[StandardPrice],S.[LastReceiptCost],S.[LastReceiptDate],S.[MinOrderQty],S.[MaxOrderQty],S.[OnOrderQty],S.[UnitMeasureCode],S.[ModifiedDate],@B FROM #CT_ProductVendor C JOIN ssis_flow.Delta_ProductVendor S ON S.[ProductID]=C.[ProductID] AND S.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[ProductVendor] R WHERE R.[ProductID]=S.[ProductID] AND R.[BusinessEntityID]=S.[BusinessEntityID]);
INSERT stg.[ProductVendor]([ProductID],[BusinessEntityID],[AverageLeadTime],[StandardPrice],[LastReceiptCost],[LastReceiptDate],[MinOrderQty],[MaxOrderQty],[OnOrderQty],[UnitMeasureCode],[ModifiedDate],LoadBatchID) SELECT R.[ProductID],R.[BusinessEntityID],R.[AverageLeadTime],R.[StandardPrice],R.[LastReceiptCost],R.[LastReceiptDate],R.[MinOrderQty],R.[MaxOrderQty],R.[OnOrderQty],R.[UnitMeasureCode],R.[ModifiedDate],@B FROM etl_raw.[ProductVendor] R JOIN #CT_ProductVendor C ON R.[ProductID]=C.[ProductID] AND R.[BusinessEntityID]=C.[BusinessEntityID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;